CREATE FUNCTION public.get_dashboard_summary() RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$ DECLARE v_uid UUID; v_balance INTEGER; v_cards JSONB; v_txns JSONB; v_warnings JSONB; BEGIN v_uid := auth.uid(); IF v_uid IS NULL THEN RAISE EXCEPTION 'not authenticated' USING ERRCODE = '28000'; END IF; SELECT COALESCE((SELECT balance_cents FROM public.wallets WHERE user_id = v_uid), 0) INTO v_balance; SELECT COALESCE(jsonb_agg(row_to_json ORDER BY created_at DESC), '[]'::JSONB) INTO v_cards FROM (SELECT id, name, spending_cap_cents, spent_cents, (spending_cap_cents - spent_cents) AS remaining, status, end_date, CASE WHEN spending_cap_cents > 0 THEN ROUND((spent_cents::NUMERIC / spending_cap_cents::NUMERIC) * 100) ELSE 0 END AS progress_pct, created_at FROM public.virtual_cards WHERE user_id = v_uid ORDER BY created_at DESC) AS row_to_json_sub; SELECT COALESCE(jsonb_agg(row_to_json ORDER BY created_at DESC), '[]'::JSONB) INTO v_txns FROM (SELECT t.id, t.card_id, t.merchant_name, t.amount_cents, t.status, t.decline_reason, t.created_at FROM public.transactions AS t JOIN public.virtual_cards AS c ON c.id = t.card_id WHERE t.user_id = v_uid ORDER BY t.created_at DESC LIMIT 5) AS row_to_json_sub2; SELECT COALESCE(jsonb_agg(w), '[]'::JSONB) INTO v_warnings FROM (SELECT jsonb_build_object('kind', 'near_cap', 'card_id', id, 'message', 'Card ' || name || ' is near its cap') AS w FROM public.virtual_cards WHERE user_id = v_uid AND status = 'active' AND spent_cents >= 0.8 * spending_cap_cents UNION ALL SELECT jsonb_build_object('kind', 'low_balance', 'card_id', NULL, 'message', 'Wallet balance is low') AS w WHERE v_balance < 2500 UNION ALL SELECT jsonb_build_object('kind', 'expired_soon', 'card_id', id, 'message', 'Card ' || name || ' expires soon') AS w FROM public.virtual_cards WHERE user_id = v_uid AND end_date IS NOT NULL AND end_date <= CURRENT_DATE + 7) AS all_warnings; RETURN jsonb_build_object('balance_cents', v_balance, 'cards', v_cards, 'recent_transactions', v_txns, 'warnings', v_warnings); END; $$; REVOKE ALL ON FUNCTION public.get_dashboard_summary() FROM PUBLIC, ANON; GRANT EXECUTE ON FUNCTION public.get_dashboard_summary() TO authenticated;
